CREATE TABLE IF NOT EXISTS accounts(id UUID PRIMARY KEY,username TEXT NOT NULL UNIQUE,record BYTEA NOT NULL,identity BYTEA NOT NULL,recovery BYTEA NOT NULL,used BIGINT NOT NULL DEFAULT 0 CHECK(used>=0));
CREATE TABLE IF NOT EXISTS key_blobs(account UUID PRIMARY KEY REFERENCES accounts ON DELETE CASCADE,bundle BYTEA NOT NULL);
CREATE TABLE IF NOT EXISTS devices(id UUID PRIMARY KEY,account UUID NOT NULL REFERENCES accounts ON DELETE CASCADE,cert BYTEA NOT NULL,revoked BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS sessions(token BYTEA PRIMARY KEY,account UUID NOT NULL REFERENCES accounts ON DELETE CASCADE,device UUID NOT NULL REFERENCES devices ON DELETE CASCADE,expires TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces(id UUID PRIMARY KEY,owner UUID NOT NULL REFERENCES accounts ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS memberships(space UUID NOT NULL REFERENCES workspaces ON DELETE CASCADE,account UUID NOT NULL REFERENCES accounts ON DELETE CASCADE,PRIMARY KEY(space,account));
CREATE TABLE IF NOT EXISTS documents(id UUID NOT NULL,space UUID NOT NULL REFERENCES workspaces ON DELETE CASCADE,seq BIGINT NOT NULL DEFAULT 0,snapshot UUID,PRIMARY KEY(space,id));
CREATE TABLE IF NOT EXISTS updates(doc UUID NOT NULL,seq BIGINT NOT NULL,device UUID NOT NULL REFERENCES devices ON DELETE CASCADE,counter BIGINT NOT NULL,digest BYTEA NOT NULL,wire BYTEA NOT NULL,space UUID NOT NULL,PRIMARY KEY(space,doc,seq),UNIQUE(space,doc,device,counter),FOREIGN KEY(space,doc) REFERENCES documents(space,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS snapshots(doc UUID NOT NULL,id UUID NOT NULL,parent UUID,covers BIGINT NOT NULL,seq BIGINT NOT NULL,space UUID NOT NULL,PRIMARY KEY(space,doc,id),FOREIGN KEY(space,doc) REFERENCES documents(space,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS blobs(id UUID NOT NULL,space UUID NOT NULL REFERENCES workspaces ON DELETE CASCADE,size BIGINT NOT NULL,PRIMARY KEY(space,id));
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS deletions(space UUID NOT NULL REFERENCES workspaces ON DELETE CASCADE,id UUID NOT NULL,PRIMARY KEY(space,id));
CREATE TABLE IF NOT EXISTS workspace_keys(space UUID PRIMARY KEY REFERENCES workspaces ON DELETE CASCADE,key_blob BYTEA NOT NULL);
ALTER TABLE documents ADD COLUMN IF NOT EXISTS base BIGINT NOT NULL DEFAULT 0;
ALTER TABLE updates ALTER COLUMN wire DROP NOT NULL;
ALTER TABLE workspaces ADD COLUMN IF NOT EXISTS mark BIGINT NOT NULL DEFAULT 0;
ALTER TABLE documents ADD COLUMN IF NOT EXISTS mark BIGINT NOT NULL DEFAULT 0;
ALTER TABLE deletions ADD COLUMN IF NOT EXISTS mark BIGINT NOT NULL DEFAULT 0;
ALTER TABLE devices ADD COLUMN IF NOT EXISTS format SMALLINT NOT NULL DEFAULT 1 CHECK(format>=1);
ALTER TABLE devices ADD COLUMN IF NOT EXISTS seen TIMESTAMPTZ NOT NULL DEFAULT now();
CREATE INDEX IF NOT EXISTS documents_changes ON documents(space,mark);
CREATE INDEX IF NOT EXISTS deletions_changes ON deletions(space,mark);
CREATE INDEX IF NOT EXISTS updates_with_wire ON updates(space,doc,seq) WHERE wire IS NOT NULL;
DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=current_schema() AND table_name='updates' AND column_name='space') THEN
ALTER TABLE updates ADD COLUMN space UUID;
ALTER TABLE snapshots ADD COLUMN space UUID;
UPDATE updates u SET space=d.space FROM documents d WHERE d.id=u.doc;
UPDATE snapshots s SET space=d.space FROM documents d WHERE d.id=s.doc;
ALTER TABLE updates ALTER COLUMN space SET NOT NULL,DROP CONSTRAINT updates_doc_fkey,DROP CONSTRAINT updates_pkey,DROP CONSTRAINT updates_doc_device_counter_key;
ALTER TABLE snapshots ALTER COLUMN space SET NOT NULL,DROP CONSTRAINT snapshots_doc_fkey,DROP CONSTRAINT snapshots_pkey;
ALTER TABLE documents DROP CONSTRAINT documents_pkey,ADD PRIMARY KEY(space,id);
ALTER TABLE updates ADD PRIMARY KEY(space,doc,seq),ADD UNIQUE(space,doc,device,counter),ADD FOREIGN KEY(space,doc) REFERENCES documents(space,id) ON DELETE CASCADE;
ALTER TABLE snapshots ADD PRIMARY KEY(space,doc,id),ADD FOREIGN KEY(space,doc) REFERENCES documents(space,id) ON DELETE CASCADE;
ALTER TABLE blobs DROP CONSTRAINT blobs_pkey,ADD PRIMARY KEY(space,id);
END IF;
END $$;
